SELECT

FROM () session_resource_files
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND session_uuid = #{params.SessionUUID}
AND path = #{params.EntryPath}
AND deleted_at IS NULL

SELECT

FROM () session_resource_files
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND session_uuid = #{params.SessionUUID}
AND path = #{params.EntryPath}
AND deleted_at IS NULL
AND (expires_at IS NULL OR expires_at > now())

SELECT

FROM () session_resource_files
WHERE uuid = #{params.ResourceUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND session_uuid = #{params.SessionUUID}
AND deleted_at IS NULL

SELECT

FROM () session_resource_files
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND session_uuid = #{params.SessionUUID}
AND uuid = #{params.ResourceUUID}
AND deleted_at IS NULL

SELECT

FROM () session_resource_files
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND session_uuid = #{params.SessionUUID}
AND path = #{params.DestinationPath}
AND deleted_at IS NULL

SELECT

FROM () session_resource_files
WHERE workspace_uuid = #{params.WorkspaceUUID}
AND session_uuid = #{params.SessionUUID}
AND kind <> 'archive'
AND deleted_at IS NULL
AND (expires_at IS NULL OR expires_at > now())


        AND left(path, char_length(#{params.DirectoryPrefix})) = #{params.DirectoryPrefix}


        AND parent_path = #{params.DirectoryPath}



    AND (path, uuid) > (#{params.CursorPath}, #{params.CursorUUID})

ORDER BY path ASC, uuid ASC
LIMIT #{params.FetchLimit}

SELECT

FROM () session_resource_files
WHERE workspace_uuid = #{workspaceUUID}
AND session_uuid = (
SELECT session_uuid
FROM filestore_filesystems
WHERE uuid = #{filesystemUUID}
AND workspace_uuid = #{workspaceUUID}
AND deleted_at IS NULL
)
AND kind = 'archive'
AND deleted_at IS NULL
ORDER BY path, id
